import { type ReactElement, useCallback, useMemo } from "react";
import { View, type ViewProps } from "react-native";
import { useControllableState } from "@registry/hooks/use-controllable-state";
import { useFieldContext } from "@registry/ui/field/field.context";
import { type RadioGroupContextValue, RadioGroupProvider } from "./radio.context";
import {
	type RadioOrientation,
	type RadioSize,
	type RadioVariant,
	radioVariants,
	shouldEmitSelection,
} from "./radio.variants";

export type RadioGroupProps = ViewProps & {
	/**
	 * The selected radio's value.
	 *
	 * `null` means "controlled, nothing selected". Omitting the prop entirely is
	 * what makes the group uncontrolled, so a `useState<string>()` seeded with
	 * `undefined` would silently hand the group its own state and then switch it
	 * to controlled on the first press. Pass `value ?? null`.
	 */
	selected?: string | null;
	/** Initial selection while uncontrolled. */
	defaultSelected?: string | null;
	/** Called with the newly selected value. Never called for a re-press of the current one. */
	onSelected?: (value: string) => void;
	/** Size of every radio in the group. */
	size?: RadioSize;
	/** How every ring in the group is painted. */
	variant?: RadioVariant;
	/** `vertical` stacks the radios; `horizontal` lays them out in a wrapping row. */
	orientation?: RadioOrientation;
	/** Marks every radio invalid. Inherited from an enclosing `Field` when not given. */
	isInvalid?: boolean;
	/** Disables every radio. Inherited from an enclosing `Field` when not given. */
	isDisabled?: boolean;
	className?: string;
};

/**
 * Groups radios and owns which one is selected.
 *
 * Selection is `selected` plus `onSelected`, or `defaultSelected` alone to let
 * the group hold its own. `size` and `variant` belong to the group outright — a
 * group whose options were different sizes is not a design — while `isDisabled`
 * and `isInvalid` are published raw, so one option can still disable itself.
 *
 * It renders no legend, description or error. `Field` already owns all three, and
 * a second definition of a label is a type scale that can drift — the trade
 * `Input` made. That does leave the group without an accessible name, since React
 * Native has no `aria-labelledby` to tie it to the `Field.Label` above it, so
 * pass `accessibilityLabel`.
 *
 * @example
 * <Radio.Group onSelected={setPlan} selected={plan ?? null} accessibilityLabel="Plan">
 *   <Radio value="free"><Radio.Label>Free</Radio.Label></Radio>
 *   <Radio value="pro"><Radio.Label>Pro</Radio.Label></Radio>
 * </Radio.Group>
 */
export function RadioGroup({
	selected: selectedProp,
	defaultSelected,
	onSelected,
	size = "md",
	variant = "primary",
	orientation = "vertical",
	isInvalid,
	isDisabled,
	className,
	...props
}: RadioGroupProps): ReactElement {
	const field = useFieldContext();

	// Memoised, or `useControllableState`'s setter rebuilds every render, which
	// rebuilds the context value, which re-renders every radio in the group on
	// every render of whatever holds it.
	const handleChange = useCallback(
		(next: string | null) => {
			if (next !== null) onSelected?.(next);
		},
		[onSelected]
	);

	const [selected, setSelected] = useControllableState<string | null>({
		value: selectedProp,
		defaultValue: defaultSelected ?? null,
		onChange: handleChange,
	});

	const select = useCallback(
		(next: string) => {
			if (shouldEmitSelection(selected, next)) setSelected(next);
		},
		[selected, setSelected]
	);

	// Deliberately not defaulted in the destructure — `false` there would swallow
	// the field before it was ever consulted. See `input-group.tsx`.
	const resolvedIsInvalid = isInvalid ?? field?.isInvalid;
	const resolvedIsDisabled = isDisabled ?? field?.isDisabled;

	const context = useMemo<RadioGroupContextValue>(
		() => ({
			isDisabled: resolvedIsDisabled,
			isInvalid: resolvedIsInvalid,
			orientation,
			select,
			selected,
			size,
			variant,
		}),
		[resolvedIsDisabled, resolvedIsInvalid, orientation, select, selected, size, variant]
	);

	return (
		<RadioGroupProvider value={context}>
			<View
				accessibilityRole="radiogroup"
				className={radioVariants({ orientation, size }).group({ className })}
				{...props}
			/>
		</RadioGroupProvider>
	);
}
RadioGroup.displayName = "DelacourUI.Radio.Group";

import { type ComponentProps, type ReactElement, type ReactNode, useEffect } from "react";
import { View, type ViewProps } from "react-native";
import Animated, { useAnimatedStyle, useSharedValue, withSpring } from "react-native-reanimated";
import { useRadioPart } from "./radio.context";
import { RADIO_DOT_SPRING, radioVariants } from "./radio.variants";

export type RadioIndicatorChildrenProps = {
	isSelected: boolean;
	isInvalid: boolean;
	size: "lg" | "md" | "sm";
	variant: "primary" | "secondary";
};
export type RadioIndicatorProps = Omit<ViewProps, "children"> & {
	className?: string;
	/** Replaces the dot. The ring, its size and its colours are still the radio's. */
	children?: ReactNode | ((props: RadioIndicatorChildrenProps) => ReactNode);
	/** Props for the dot's own `Animated.View`, for a caller restyling it in place. */
	dotProps?: Omit<ComponentProps<typeof Animated.View>, "children" | "className"> & { className?: string };
};

/**
 * The circle: a ring, and the dot that scales into it when the radio is selected.
 *
 * Composed in automatically as the radio's first child, so write it out by hand
 * only to move it — a trailing indicator is `<Radio.Indicator />` placed last —
 * or to replace the dot with children of your own.
 *
 * **Drawn from `View`s rather than a Central Icon.** Rule 5 governs icons, and
 * `Spinner`'s arc is the precedent for primitives; here the set has no
 * ring-with-a-centred-dot glyph at all. Two things follow from drawing it: the
 * dot can scale from the ring's centre entirely on the UI thread, and the ring's
 * four themed colours stay classes in `radio.variants.ts` where `bun test`
 * reaches them. An `Icon` would take its colour as a resolved value, splitting
 * one decision across two mechanisms.
 *
 * **The animated style lives on the dot, never on the ring.** `Pressable`'s root
 * `Animated.View` already owns `opacity` and `transform` through a
 * `useAnimatedStyle` of its own, and two animated styles on one node fight for
 * the same props. The dot is a descendant two levels down, so the two never
 * contend — which is also why `Radio` takes no `asChild`.
 *
 * **Reduce motion is left at Reanimated's default `System`, deliberately the
 * opposite call to `Spinner`'s `ReduceMotion.Never`.** The spinner needs `Never`
 * because a zero-length animation inside `withRepeat(-1)` would spin forever.
 * Here the state is carried by the dot's *presence*, not by its motion, so
 * `System` snapping straight to the target is exactly the right degradation.
 */
export function RadioIndicator({ className, children, dotProps, ...props }: RadioIndicatorProps): ReactElement {
	const { size, variant, isSelected, isInvalid } = useRadioPart("Radio.Indicator");
	// Seeded from the current state rather than from zero, so a group that mounts
	// with a selection does not animate every dot in on its first paint.
	const progress = useSharedValue(isSelected ? 1 : 0);

	useEffect(() => {
		progress.value = withSpring(isSelected ? 1 : 0, RADIO_DOT_SPRING);
	}, [isSelected, progress]);

	// Both branches animate: the outgoing dot shrinks rather than vanishing, which
	// is what makes a group read as one selection moving between rows.
	const dotStyle = useAnimatedStyle(() => ({
		opacity: progress.value,
		transform: [{ scale: progress.value }],
	}));

	const slots = radioVariants({ isInvalid, isSelected, size, variant });

	const renderChildren = () => {
		if (typeof children === "function") {
			return children({ isSelected, isInvalid, size, variant });
		}

		if (children) {
			return children;
		}

		return null;
	};

	return (
		<View className={slots.indicator({ className })} {...props}>
			{renderChildren() ?? (
				<Animated.View
					{...dotProps}
					className={slots.dot({ className: dotProps?.className })}
					style={[dotStyle, dotProps?.style]}
				/>
			)}
		</View>
	);
}
RadioIndicator.displayName = "DelacourUI.Radio.Indicator";

import type { ReactElement } from "react";
import { Text, type TextPresetProps } from "@registry/ui/text";
import { useRadioPart } from "./radio.context";
import { RADIO_LABEL_TEXT_SIZE, radioVariants } from "./radio.variants";

export type RadioLabelProps = TextPresetProps;

/**
 * The radio's text, inside the radio's own tap target.
 *
 * Not a duplicate of `Field.Label`, and the distinction is the point: a
 * `Field.Label` names the whole control from outside it, while this sits *within*
 * one radio's press area, so tapping the word selects that option.
 *
 * Renders `Text.Label` and names a size, never a scale of its own. The weight and
 * the colour belong to the preset — restating them here would be a second
 * definition of `Text.Label` that could drift from it, the rule `Field` is built
 * on. Naming the size is what lets the label still track the radio's own axis,
 * since `Text`'s size axis is built to beat its preset.
 *
 * **It does not redden while invalid.** The ring already carries that, and a
 * `Field.Error` under the group says what is actually wrong; five labels turning
 * red would read as five wrong answers. Disabled needs nothing here either: the
 * `label` slot carries its own `opacity-50`, and the `indicator` slot carries a
 * matching one, so the ring and the label fade together as one control. Neither
 * fade may move to the `root` — see {@link radioVariants}.
 */
export function RadioLabel({ className, size, ...props }: RadioLabelProps): ReactElement {
	const { size: radioSize, variant, isSelected, isInvalid } = useRadioPart("Radio.Label");

	return (
		<Text.Label
			className={radioVariants({ isInvalid, isSelected, size: radioSize, variant }).label({ className })}
			size={size ?? RADIO_LABEL_TEXT_SIZE[radioSize]}
			{...props}
		/>
	);
}
RadioLabel.displayName = "DelacourUI.Radio.Label";

import { createContext, type ReactElement, type ReactNode, use } from "react";
import type { RadioOrientation, RadioSize, RadioVariant } from "./radio.variants";

export type RadioGroupContextValue = {
	/** The selected radio's value. `null` is "nothing selected", never `undefined`. */
	selected: string | null;
	/** What a radio calls on press. Stays quiet when the value is already selected. */
	select: (value: string) => void;
	/** Size of every radio in the group. The group owns this axis outright. */
	size: RadioSize;
	/** How every ring in the group is painted. The group owns this axis outright. */
	variant: RadioVariant;
	/** Which way the group lays its radios out. */
	orientation: RadioOrientation;
	/**
	 * Raw rather than resolved, and deliberately so.
	 *
	 * `Input.Group` publishes these settled because it draws a box whose state it
	 * has to paint. A radio group paints nothing, and it holds many radios — so
	 * leaving `undefined` to mean "the group said nothing" is what lets a single
	 * option disable itself. A group that does name the axis still wins outright.
	 */
	isDisabled?: boolean;
	isInvalid?: boolean;
};

export type RadioContextValue = {
	/** Size of the radio, already settled from group, own props and field. */
	size: RadioSize;
	/** How the ring is painted, already settled. */
	variant: RadioVariant;
	/** Whether this radio is the selection. */
	isSelected: boolean;
	/** Whether this radio is unavailable. */
	isDisabled: boolean;
	/** Whether this radio reports an invalid value. */
	isInvalid: boolean;
};

const RadioGroupContext = createContext<RadioGroupContextValue | null>(null);
const RadioContext = createContext<RadioContextValue | null>(null);

/**
 * Supplies the enclosing group's selection and axes to the radios inside it.
 *
 * Lives in its own module, importing nothing but React and types, so a part can
 * read it without importing `./radio` or `./radio-group`. That import would close
 * a cycle, and Metro serves a partially initialised module for a cycle — leaving
 * the context `undefined` at import time and red-boxing the app on a cold start.
 */
export function RadioGroupProvider({
	value,
	children,
}: {
	value: RadioGroupContextValue;
	children: ReactNode;
}): ReactElement {
	return <RadioGroupContext value={value}>{children}</RadioGroupContext>;
}
RadioGroupProvider.displayName = "DelacourUI.Radio.Group.Provider";

/**
 * Supplies one radio's settled state to its own parts.
 *
 * What the parts read is always the *resolved* state, so `Radio.Indicator` never
 * has to know whether it is inside a group, never reads a `Field`, and never
 * imports the root.
 */
export function RadioProvider({ value, children }: { value: RadioContextValue; children: ReactNode }): ReactElement {
	return <RadioContext value={value}>{children}</RadioContext>;
}
RadioProvider.displayName = "DelacourUI.Radio.Provider";

/**
 * The enclosing group's context, or null outside a `<Radio.Group>`.
 *
 * This is the export the radio root reads: it is nullable because a radio has to
 * work perfectly well on its own, the same way `useFieldContext` is nullable for
 * every control that can stand outside a `Field`.
 */
export function useRadioGroupContext(): RadioGroupContextValue | null {
	return use(RadioGroupContext);
}

/**
 * Reads the enclosing group's selection and axes.
 *
 * For a custom control that has to match the group it sits in. Throws outside
 * one — use {@link useRadioGroupContext} where the group is optional.
 */
export function useRadioGroup(): RadioGroupContextValue {
	const context = useRadioGroupContext();
	if (!context) {
		throw new Error("useRadioGroup must be called inside a <Radio.Group>.");
	}
	return context;
}

/** The enclosing radio's settled state, or null outside a `<Radio>`. */
export function useRadioContext(): RadioContextValue | null {
	return use(RadioContext);
}

/**
 * Reads the enclosing radio's settled state.
 *
 * Lets a custom child style itself to match without the radio having to pass
 * props down through every slot. Throws outside a `<Radio>` — use
 * {@link useRadioContext} where the enclosing radio is optional.
 */
export function useRadio(): RadioContextValue {
	const context = useRadioContext();
	if (!context) {
		throw new Error("useRadio must be called inside a <Radio>.");
	}
	return context;
}

/**
 * The enclosing radio's state, for a compound part that cannot work without one.
 *
 * Internal: deliberately not re-exported from `index.ts`. A caller outside the
 * library wants {@link useRadio}, whose error message names the hook rather than
 * a part.
 */
export function useRadioPart(component: string): RadioContextValue {
	const context = useRadioContext();
	if (!context) {
		throw new Error(`${component} must be rendered inside a <Radio>.`);
	}
	return context;
}

import { Children, isValidElement, type ReactElement, type ReactNode, useCallback, useMemo } from "react";
import { useFieldContext } from "@registry/ui/field/field.context";
import { Pressable, type PressableProps } from "@registry/ui/pressable";
import { TextClassProvider } from "@registry/ui/text/text.context";
import { resolveTextClass } from "@registry/ui/text/text.variants";
import { type RadioContextValue, RadioProvider, useRadioGroupContext } from "./radio.context";
import {
	RADIO_LABEL_TEXT_SIZE,
	type RadioSize,
	type RadioVariant,
	radioVariants,
	resolveIndicatorPlacement,
	resolveRadioState,
} from "./radio.variants";
import { RadioGroup } from "./radio-group";
import { RadioIndicator } from "./radio-indicator";
import { RadioLabel } from "./radio-label";

export type RadioProps = Omit<PressableProps, "asChild" | "busy" | "children" | "disabled"> & {
	/** Identifies this radio to its `Radio.Group`. Required there; inert without one. */
	value?: string;
	/** Selected state for a radio standing on its own. Ignored inside a `Radio.Group`. */
	isSelected?: boolean;
	/** Initial selected state while uncontrolled and ungrouped. */
	defaultSelected?: boolean;
	/**
	 * Called when this radio becomes the selection. Ignored inside a
	 * `Radio.Group`, which owns the callback.
	 *
	 * Only ever called with `true`: a radio does not deselect itself, which is
	 * `Switch` and `Checkbox` semantics rather than radio ones.
	 */
	onSelected?: (isSelected: boolean) => void;
	/** Ignored inside a `Radio.Group` — the group owns this axis. */
	size?: RadioSize;
	/** Ignored inside a `Radio.Group` — the group owns this axis. */
	variant?: RadioVariant;
	/** Wins over an enclosing `Field`. A group that names it wins over both. */
	isInvalid?: boolean;
	/** Wins over an enclosing `Field`. A group that names it wins over both. */
	isDisabled?: boolean;
	children?: ReactNode;
};

function RadioRoot({
	value,
	isSelected,
	defaultSelected,
	onSelected,
	size,
	variant,
	isInvalid,
	isDisabled,
	feedback = "fade",
	hitSlop = 8,
	className,
	children,
	onPress,
	...props
}: RadioProps): ReactElement {
	const group = useRadioGroupContext();
	const field = useFieldContext();

	const state = resolveRadioState({
		field,
		group,
		own: { isDisabled, isInvalid, isSelected, size, value, variant },
	});

	if (process.env.NODE_ENV !== "production" && group && value === undefined) {
		console.warn("Radio: a <Radio> inside a <Radio.Group> needs a `value`, or it can never be selected.");
	}

	const handlePress = useCallback(() => {
		if (group) {
			if (value !== undefined) group.select(value);
		} else if (!state.isSelected) {
			onSelected?.(true);
		}
		onPress?.();
	}, [group, onPress, onSelected, state.isSelected, value]);

	const context = useMemo<RadioContextValue>(
		() => ({
			isDisabled: state.isDisabled,
			isInvalid: state.isInvalid,
			isSelected: state.isSelected,
			size: state.size,
			variant: state.variant,
		}),
		[state.isDisabled, state.isInvalid, state.isSelected, state.size, state.variant]
	);

	const { content, placement } = useMemo(() => withIndicator(children), [children]);

	// One treatment covers the whole subtree — a radio row has a label and no
	// description part — which is the condition for publishing into the cascade.
	const labelClass = useMemo(
		() => resolveTextClass({ size: RADIO_LABEL_TEXT_SIZE[state.size], variant: "label" }),
		[state.size]
	);

	return (
		<RadioProvider value={context}>
			<Pressable
				accessibilityRole="radio"
				accessibilityState={{ checked: state.isSelected }}
				className={radioVariants({
					isDisabled: state.isDisabled,
					isIndicatorTrailing: placement === "end",
					size: state.size,
				}).root({ className })}
				disabled={state.isDisabled}
				feedback={feedback}
				hitSlop={hitSlop}
				onPress={handlePress}
				{...props}
			>
				<TextClassProvider value={labelClass}>{content}</TextClassProvider>
			</Pressable>
		</RadioProvider>
	);
}

/**
 * Wraps bare text in a `Radio.Label` and settles where the indicator sits.
 *
 * React Native cannot render a string outside a `<Text>`, so `<Radio>Yes</Radio>`
 * would otherwise crash. Consecutive strings and numbers collapse into one label
 * rather than one each — `Plan {n}` is a single piece of text, and wrapping the
 * parts separately would space them apart by the row's own gap.
 *
 * An indicator is composed in at the front only when the children hold none,
 * which is what buys a settings row for free: place a `<Radio.Indicator />` last
 * and the row lays out `[label and description] [ring]`, spread to the far edge,
 * with nothing else said. {@link resolveIndicatorPlacement} is that decision and
 * is pure, so `bun test` reaches it.
 *
 * Lives here rather than with the parts: it is the root that wraps its own
 * children, and importing it from a part would close a cycle. See AGENTS.md.
 */
function withIndicator(children: ReactNode): { content: ReactNode; placement: "start" | "end" | "none" } {
	const items = Children.toArray(children);
	const output: ReactNode[] = [];
	const isIndicator: boolean[] = [];
	let run: (string | number)[] = [];

	const flushRun = () => {
		if (run.length === 0) return;
		output.push(<RadioLabel key={`label-${output.length}`}>{run.join("")}</RadioLabel>);
		isIndicator.push(false);
		run = [];
	};

	for (const child of items) {
		if (typeof child === "string" || typeof child === "number") {
			run.push(child);
			continue;
		}
		flushRun();
		output.push(child);
		isIndicator.push(isValidElement(child) && child.type === RadioIndicator);
	}
	flushRun();

	const placement = resolveIndicatorPlacement(isIndicator);
	if (placement !== "none") return { content: output, placement };

	return { content: [<RadioIndicator key="indicator" />, ...output], placement: "start" };
}

/**
 * One option in a set where exactly one can be chosen.
 *
 * The whole row is the control: the ring, the label beside it and the space
 * between them are one tap target, so a press anywhere on the row selects. A
 * `Radio.Indicator` is composed in automatically and plain string children are
 * wrapped in a `Radio.Label`, so the shortest thing that works is `<Radio
 * value="pro">Pro</Radio>`.
 *
 * **A radio works with or without a group.** Inside a `Radio.Group` its `value`
 * identifies it and the group owns the selection, the size and the variant.
 * Outside one it is driven by its own `isSelected` and `onSelected`.
 *
 * Nearest wins for state: a group first, this radio's own props next, an
 * enclosing `Field` last — so a radio inside an invalid `Field` turns danger with
 * nothing said at the call site, while `isInvalid={false}` still opts out.
 *
 * A radio whose row holds no text needs an `accessibilityLabel`, the same rule an
 * icon-only `Button` follows.
 *
 * @example
 * <Radio.Group onSelected={setPlan} selected={plan ?? null} accessibilityLabel="Plan">
 *   <Radio value="free">Free</Radio>
 *   <Radio value="pro">Pro</Radio>
 * </Radio.Group>
 *
 * @example
 * <Radio value="express">
 *   <Radio.Label>Express</Radio.Label>
 *   <Text.Caption>Arrives tomorrow.</Text.Caption>
 * </Radio>
 *
 * @example
 * <Radio accessibilityLabel="Express delivery" isSelected={isExpress} onSelected={setExpress} />
 */
export const Radio = Object.assign(RadioRoot, {
	/** The radio's text, inside its tap target. Takes its size step from the radio's own. */
	Label: RadioLabel,
	/** The ring and its dot. Composed in automatically; write it out to move or replace it. */
	Indicator: RadioIndicator,
	/** Groups radios and owns which one is selected. */
	Group: RadioGroup,
	displayName: "DelacourUI.Radio",
});

import type { VariantProps } from "tailwind-variants";
import { tv } from "@registry/lib/tv";
import type { TextSize } from "@registry/ui/text/text.variants";

/** How the ring is painted. `secondary` fills it; `primary` leaves it hollow. */
export const RADIO_VARIANTS = ["primary", "secondary"] as const;

export const RADIO_SIZES = ["sm", "md", "lg"] as const;

/** Which way a `Radio.Group` lays its radios out. */
export const RADIO_ORIENTATIONS = ["vertical", "horizontal"] as const;

export type RadioVariant = (typeof RADIO_VARIANTS)[number];
export type RadioSize = (typeof RADIO_SIZES)[number];
export type RadioOrientation = (typeof RADIO_ORIENTATIONS)[number];

/**
 * The axes a radio falls back to when neither it nor its group names one.
 *
 * Named once because two places read them — `defaultVariants` below and
 * {@link resolveRadioState}, which runs before `tv` is ever called. A test pins
 * the pair, since a drift between them is a radio that renders at one size and
 * reports another.
 */
export const RADIO_DEFAULT_SIZE: RadioSize = "md";
export const RADIO_DEFAULT_VARIANT: RadioVariant = "primary";

/**
 * The spring the dot scales in and out on.
 *
 * Deliberately near `Pressable`'s `PRESS_SPRING` but a touch looser, so the dot
 * settles just after the row it sits in has rebounded. Read on the JS thread
 * inside an effect rather than captured by a worklet, so it stays a plain object.
 */
export const RADIO_DOT_SPRING = { damping: 16, mass: 0.4, stiffness: 300 } as const;

/**
 * The `Text` size step each radio size hands its label.
 *
 * `Radio.Label` renders `Text.Label` and names this step, rather than restating
 * a type scale in the `label` slot. `Text`'s own size axis is built to beat its
 * preset, so this keeps the weight and the colour in exactly one place — the
 * preset — while still letting the label track the radio's size. A test asserts
 * every value here is a size `Text` actually has.
 */
export const RADIO_LABEL_TEXT_SIZE: Record<RadioSize, TextSize> = { sm: "sm", md: "md", lg: "lg" };

/**
 * Styling for every part of a radio, and for the group that holds one.
 *
 * One slotted `tv()` rather than a call per part, because `radio-indicator.tsx`
 * and `radio-label.tsx` cannot import the root without closing a cycle (AGENTS.md
 * rule 3) yet all three read the same `size`, `variant` and `isSelected`.
 *
 * **The root takes no `self-start` and no `w-full`, and both absences are
 * load-bearing.** A radio row *is* its own tap target, so unlike a `Badge` it
 * wants the stretch it gets inside the group's `flex-col` — `self-start` would
 * shrink the target to the width of the word "Yes". But unlike a `ListGroup.Item`
 * it cannot take `w-full` either, because a `horizontal` group would then give
 * every radio the full width of the group and blow the row apart. Vertical
 * stretch already supplies the width; horizontal wants content width.
 *
 * **The label is `shrink`, never `flex-1`.** `flex-1` sets `flex-basis: 0%`, and
 * in a content-sized `horizontal` row Yoga resolves that to zero and collapses
 * the text to nothing. `shrink` lets a long label wrap without claiming a basis.
 *
 * **The row's height is a floor, never fixed.** `Text` respects OS font scaling,
 * so `h-*` would clip a label at a large accessibility step; `min-h-*` exists for
 * the hit target, which scaling may exceed but must never undercut.
 *
 * The ring indexes the shared `--spacing-icon-*` scale rather than minting one of
 * its own — a radio's ring is a small round mark in a row beside a label, the
 * same kind of thing as a row's chevron, and it should stay level with an `Icon`
 * at the same step by construction. The dot takes plain spacing steps and its
 * fit inside the ring is pinned by a test rather than by a token, the way
 * `Field` pins its gap ladder.
 *
 * `border-2` sits in the base rather than on a variant: a border declared only
 * where it is coloured would make the ring four points smaller the moment a
 * caller switched variant.
 *
 * No slot worn by a `View` carries `text-*`, and the `label` slot carries no type
 * scale, weight or colour at all — see {@link RADIO_LABEL_TEXT_SIZE}.
 *
 * Free of React Native imports so it stays unit-testable — `bun test` cannot
 * parse React Native's Flow-typed source. See AGENTS.md.
 */
export const radioVariants = tv({
	slots: {
		/** The group's box. Paints no state of its own — see the note below. */
		group: "w-full",
		/** The pressable row. Deliberately neither `self-start` nor `w-full`. */
		root: "flex-row items-center",
		/** The ring. Its colour is a class, so the whole matrix stays in `bun test`. */
		indicator: "items-center justify-center rounded-full border-2",
		/** The inner dot. Its scale and opacity are an animated style, never a class. */
		dot: "rounded-full bg-primary",
		/** Handed to a `Text.Label`. Layout only. */
		label: "shrink",
	},
	variants: {
		orientation: {
			vertical: { group: "flex-col" },
			horizontal: { group: "flex-row flex-wrap items-center" },
		},
		size: {
			sm: { group: "gap-2", root: "min-h-9 gap-2", indicator: "size-icon-md", dot: "size-1.5" },
			md: { group: "gap-3", root: "min-h-11 gap-2.5", indicator: "size-icon-lg", dot: "size-2" },
			lg: { group: "gap-3.5", root: "min-h-12 gap-3", indicator: "size-icon-xl", dot: "size-2.5" },
		},
		// The empty branches are load-bearing typing, not placeholders. `tv`
		// derives the prop type from the declared keys, so a map with only `true`
		// types the prop as `true` rather than `boolean`. See button.variants.ts.
		variant: { primary: {}, secondary: {} },
		isSelected: { true: {}, false: {} },
		isInvalid: { true: {}, false: {} },
		// A trailing ring turns the row into a settings row: the content takes the
		// left, the ring the far right. Declared here rather than left to a
		// caller's `justify-between` because the root already knows where the
		// indicator landed — see {@link resolveIndicatorPlacement}.
		isIndicatorTrailing: { true: { root: "justify-between" }, false: {} },
		// The fade lands on the children, never on the `root`, and that is not a
		// style choice. `root` is worn by `Pressable`'s own `Animated.View`, whose
		// `useAnimatedStyle` writes `opacity` on every frame — at rest, 1. An
		// `opacity-50` class on that node is overwritten before it is ever drawn,
		// silently, so the row stays at full contrast while behaving as disabled.
		// The ring and the label are ordinary descendants, so their opacity
		// multiplies with the root's instead of fighting it.
		//
		// The group must not fade either, or a disabled group would compound
		// `opacity-50` with each of its rows and land at a quarter opacity.
		isDisabled: { true: { indicator: "opacity-50", label: "opacity-50" }, false: {} },
	},
	compoundVariants: [
		// Neither `variant` nor `isSelected` paints the ring alone, so all four
		// cells live here — the reason a badge's twenty-four do.
		{ variant: "primary", isSelected: false, class: { indicator: "border-input bg-transparent" } },
		{ variant: "primary", isSelected: true, class: { indicator: "border-primary bg-transparent" } },
		{ variant: "secondary", isSelected: false, class: { indicator: "border-border bg-secondary" } },
		{ variant: "secondary", isSelected: true, class: { indicator: "border-primary bg-secondary" } },
		// Invalid outranks selected, and it is a compound rather than a plain
		// variant purely for emission order: `tv` emits the variants first and the
		// compounds after, so a plain `isInvalid` branch would lose to the four
		// cells above. `Input` leans on the same mechanism for focused-and-invalid.
		{ isInvalid: true, class: { indicator: "border-danger", dot: "bg-danger" } },
	],
	defaultVariants: {
		orientation: "vertical",
		size: RADIO_DEFAULT_SIZE,
		variant: RADIO_DEFAULT_VARIANT,
		isSelected: false,
		isInvalid: false,
		isDisabled: false,
		isIndicatorTrailing: false,
	},
});

/**
 * Where the caller put the indicator among a radio's children.
 *
 * `none` means they wrote no indicator at all, so the root composes one in at the
 * front. `end` means they placed one last with something before it — a settings
 * row, `[label and description] [ring]` — and the row spreads to push the ring to
 * the far edge. A lone indicator with nothing beside it is `start`: there is
 * nothing to spread it away from.
 *
 * This is what makes the trailing ring work without a `flex-1` spacer wedged
 * between the two, which is the shape a caller would otherwise have to reach for.
 *
 * Takes an array of "is this child an indicator" rather than the children
 * themselves, so it stays free of React and reachable from `bun test` — the trade
 * `resolveSpinnerSwapIndex` already makes.
 */
export function resolveIndicatorPlacement(isIndicator: readonly boolean[]): "start" | "end" | "none" {
	if (!isIndicator.some(Boolean)) return "none";
	if (isIndicator.length > 1 && isIndicator[isIndicator.length - 1]) return "end";
	return "start";
}

/** What an enclosing `Radio.Group` publishes, or null for a radio standing alone. */
export type RadioGroupState = {
	/** The selected value. `null` is "nothing selected", never `undefined`. */
	selected: string | null;
	size: RadioSize;
	variant: RadioVariant;
	/** Raw rather than resolved, so `??` can see past a group that named nothing. */
	isDisabled?: boolean;
	isInvalid?: boolean;
};

/** What a radio was given at its own call site. */
export type RadioOwnState = {
	value?: string;
	isSelected?: boolean;
	isDisabled?: boolean;
	isInvalid?: boolean;
	size?: RadioSize;
	variant?: RadioVariant;
};

/** What an enclosing `Field` publishes, or null outside one. */
export type RadioFieldState = { isDisabled?: boolean; isInvalid?: boolean };

/** Every axis settled, ready to hand to {@link radioVariants} and to context. */
export type RadioState = {
	size: RadioSize;
	variant: RadioVariant;
	isSelected: boolean;
	isDisabled: boolean;
	isInvalid: boolean;
	/** Whether a `Radio.Group` is driving this radio. */
	isGrouped: boolean;
};

/**
 * Settles a radio's axes from the three places they can come from.
 *
 * **Nearest wins**, the ladder `Input` already runs: a `Radio.Group` first, the
 * radio's own props next, an enclosing `Field` last. A field with no props of its
 * own turns danger with the `Field` around it, while `<Radio isInvalid={false} />`
 * still opts out of one.
 *
 * The two axes a group owns outright — `size` and `variant` — are published
 * resolved, so a grouped radio's own copies are ignored: a group whose options
 * were different sizes is not a design. The two *state* axes are published raw,
 * which is the one place this differs from `Input.Group`, and deliberately: a
 * group holds many radios, so disabling one option out of five has to be
 * possible. A group that names the axis still wins outright.
 *
 * Selection is the group's to decide when there is one. A radio carrying no
 * `value` inside a group can never be selected — the dev warning for that lives
 * in `radio.tsx`, where the component name is available to name in the message.
 *
 * Pure, so the whole matrix is reachable from `bun test`. `Input` runs this same
 * ladder inline in its own render, where no unit test can see it. See AGENTS.md.
 */
export function resolveRadioState({
	group,
	own,
	field,
}: {
	group?: RadioGroupState | null;
	own?: RadioOwnState;
	field?: RadioFieldState | null;
}): RadioState {
	const isGrouped = group != null;

	return {
		size: group?.size ?? own?.size ?? RADIO_DEFAULT_SIZE,
		variant: group?.variant ?? own?.variant ?? RADIO_DEFAULT_VARIANT,
		isDisabled: group?.isDisabled ?? own?.isDisabled ?? field?.isDisabled ?? false,
		isInvalid: group?.isInvalid ?? own?.isInvalid ?? field?.isInvalid ?? false,
		isSelected: isGrouped ? own?.value !== undefined && group.selected === own.value : (own?.isSelected ?? false),
		isGrouped,
	};
}

/**
 * Whether a press should write a new selection at all.
 *
 * Re-picking the option already selected is not a change, and a radio group has
 * no deselect gesture — so without this a tap on the current selection would
 * re-notify the caller with a value it already holds. HTML's own radio does not
 * fire `change` there either.
 *
 * Pure, so it is reachable from `bun test`. See AGENTS.md.
 */
export function shouldEmitSelection(current: string | null, next: string): boolean {
	return current !== next;
}

export type RadioVariantProps = VariantProps<typeof radioVariants>;
